import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const node = new Group();

  // --- Backdrop Plane -------------------------------------------------
  const planeWidth = 2.5;
  const planeHeight = 2.5;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    transparent: true,
  });
  const plane = new Mesh(geometry, material);
  node.add(plane);

  // Load texture asynchronously (material updated when ready)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text ------------------------------------------------------------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const color =
      (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2';
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'left',
    });
    // Slightly lift text above the plane to avoid Z‑fighting
    textObj.position.set(0, 0, 0.01);
    node.add(textObj);
  }

  // --- Event Handlers ---------------------------------------------------
  node.userData.handlers = {};

  // --- Cinematic Primitives ---------------------------------------------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handle = ctx.primitives[prim.name](node, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // --- Cleanup ----------------------------------------------------------
  const baseCleanup = () => {
    geometry.dispose();
    material.dispose();
    // No GSAP timelines in this node, but ensure any exist are killed
    if (node.userData._gsapTimeline) {
      node.userData._gsapTimeline.kill();
    }
  };

  node.userData.cleanup = () => {
    // Primitive cleanups
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }
    baseCleanup();
  };

  return node;
}
